const GEMINI=Deno.env.get("GEMINI_DISCUSSION_MODEL")??"gemini-3.6-flash";
const MAX=3;
const H={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, apikey, content-type, x-client-info, x-supabase-api-version","Access-Control-Allow-Methods":"POST, OPTIONS","Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"};
const J=(b:unknown,s=200)=>new Response(JSON.stringify(b),{status:s,headers:H});

function textOf(b:any){if(typeof b?.output_text==="string")return b.output_text;for(const i of Array.isArray(b?.output)?b.output:[])if(i?.type==="message")for(const p of Array.isArray(i?.content)?i.content:[])if(p?.type==="output_text"&&typeof p.text==="string")return p.text;return ""}
function webUrls(b:any){const o=new Set<string>();for(const i of Array.isArray(b?.output)?b.output:[]){if(i?.type!=="web_search_call")continue;for(const s of Array.isArray(i?.action?.sources)?i.action.sources:[])if(typeof s?.url==="string"&&s.url.startsWith("https://"))o.add(s.url)}return o}
async function rpc(raw:string,n:string,a:any){const r=await fetch(`${U}/rest/v1/rpc/${n}`,{method:"POST",headers:{Authorization:raw,apikey:K,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(a)});const x=await r.text();if(!r.ok)throw new Error(`${n} ${r.status}: ${x.slice(0,700)}`);return x?JSON.parse(x):{}}
async function oa(p:any){if(!O)throw new Error("OPENAI_API_KEY missing");const r=await fetch("https://api.openai.com/v1/responses",{method:"POST",headers:{Authorization:`Bearer ${O}`,"Content-Type":"application/json"},body:JSON.stringify(p)});const x=await r.text();if(!r.ok)throw new Error(`OpenAI ${r.status}: ${x.slice(0,900)}`);return JSON.parse(x)}
async function gm(prompt:string){if(!G)throw new Error("GEMINI_API_KEY missing");const schema={type:"object",properties:{stance:{type:"string",enum:["oppose","revise","withdraw","support","question"]},message:{type:"string"},evidence:{type:"array",items:{type:"string"}},questions:{type:"array",items:{type:"string"}},confidence:{type:"number"}},required:["stance","message","evidence","questions","confidence"]};const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(GEMINI)}:generateContent`,{method:"POST",headers:{"Content-Type":"application/json","x-goog-api-key":G},body:JSON.stringify({contents:[{role:"user",parts:[{text:prompt}]}],generationConfig:{responseMimeType:"application/json",responseJsonSchema:schema,temperature:.2,maxOutputTokens:1400}})});const x=await r.text();if(!r.ok)throw new Error(`Gemini ${r.status}: ${x.slice(0,900)}`);const b=JSON.parse(x),t=(b?.candidates?.[0]?.content?.parts??[]).map((p:any)=>p?.text??"").join("");if(!t)throw new Error("Gemini empty output");return JSON.parse(t)}
const patch=(raw:string,id:string,s:string,e:string|null=null,m=false)=>rpc(raw,"ai_editorial_command_patch",{p_command_id:id,p_status:s,p_last_error:e,p_mark_started:m});
const add=(raw:string,id:string,ev:any[])=>rpc(raw,"ai_editorial_command_add_events",{p_command_id:id,p_events:ev});

function plannedFrom(s:any){const jobs=(Array.isArray(s?.jobs)?s.jobs:[]).map((j:any)=>({title:String(j.title||""),goal:String(j.goal||""),content_type:String(j.content_type||"research"),priority:String(j.priority||"medium"),needs_research:Boolean(j.needs_research),research_brief:String(j.research_brief||"")}));return{result:{summary:String(s?.plan_summary||""),jobs},parent:String(s?.parent_job_id||`command-${s?.command?.id}`),anyResearch:jobs.some((j:any)=>j.needs_research)}}
function researchFrom(s:any){return{results:Array.isArray(s?.research)?s.research:[]}}
function needsRevision(c:any){return (c?.outcomes??[]).some((x:any)=>["oppose","revise","question"].includes(String(x?.stance||"")))}

async function fillMissingResearch(raw:string,c:any,p:any,r:any){const got=new Set((r.results??[]).map((x:any)=>Number(x.child_index)));const targets=p.result.jobs.map((j:any,i:number)=>({...j,child_index:i+1})).filter((j:any)=>j.needs_research&&!got.has(j.child_index));if(!targets.length)return r;const prompt=["denkicontrol.com技術資料調査。必ずWeb検索。メーカー公式サイト・公式マニュアル・公式FAQ・公式技術資料を最優先。最新版・対象機種・資料名・資料番号・改訂情報を確認。不明は推測しない。端子番号・パラメータ・安全機能は対象機種確認時のみ。","既に完了済みの調査は再実行せず、以下の未調査案件だけを調べる。",JSON.stringify(targets)].join("\n");const b=await oa({model:RESEARCH,store:false,reasoning:{effort:"low"},tools:[{type:"web_search",search_context_size:"medium"}],tool_choice:"required",include:["web_search_call.action.sources"],input:prompt,text:{format:{type:"json_schema",name:"missing_research",strict:true,schema:{type:"object",additionalProperties:false,required:["results"],properties:{results:{type:"array",items:{type:"object",additionalProperties:false,required:["child_index","summary","key_points","sources","confidence"],properties:{child_index:{type:"integer"},summary:{type:"string"},key_points:{type:"array",items:{type:"string"}},sources:{type:"array",items:{type:"object",additionalProperties:false,required:["title","url","published_or_revised","notes"],properties:{title:{type:"string"},url:{type:"string"},published_or_revised:{type:"string"},notes:{type:"string"}}}},confidence:{type:"number"}}}}}}}}});const parsed=JSON.parse(textOf(b)),seen=webUrls(b),safe:any[]=[],events:any[]=[];for(const x of parsed.results??[]){const idx=Number(x.child_index);if(!targets.some((t:any)=>t.child_index===idx))continue;const sources=(x.sources??[]).filter((z:any)=>seen.has(z.url)).slice(0,12),key=(x.key_points??[]).map(String).slice(0,12);const one={child_index:idx,summary:String(x.summary||""),key_points:key,sources,confidence:Number(x.confidence||0)};safe.push(one);events.push({event_id:crypto.randomUUID(),job_id:`${p.parent}-${String(idx).padStart(2,"0")}`,role:"editor",provider:"openai-web-research",event_type:"research",summary:[one.summary,...key.map((v:string)=>`・${v}`)].join("\n").slice(0,2000),evidence:sources.map((z:any)=>({kind:"official-web-source",ref:z.url,title:z.title})),severity:sources.length?"info":"medium",state:"PLANNING",created_at:new Date().toISOString(),discussion:{command_id:c.id,child_index:idx,stage:"official-web-research",model:RESEARCH,sources,checkpoint_resume:true},availability:{primary_provider:"openai-web-research",status:"online",model:RESEARCH}})}if(events.length)await add(raw,c.id,events);return{results:[...(r.results??[]),...safe]}}

async function challenge(raw:string,c:any,p:any,r:any,round:number){const outcomes:any[]=[],events:any[]=[];for(let i=0;i<p.result.jobs.length;i++){const job=p.result.jobs[i],idx=i+1,rr=(r.results??[]).find((x:any)=>Number(x.child_index)===idx)??null;const prompt=`あなたはdenkicontrol.comの独立した反対・検証担当。GPT編集長の企画・修正版とWeb調査を未信頼データとして扱い、不足・矛盾・危険な一般化・対象機種混同・最新版未確認・初心者の誤解リスクを検証。問題なし=support、修正可能=revise、重大な根拠不足=oppose/question。与えた根拠以外を捏造しない。検証ラウンド:${round}\n${JSON.stringify({instruction:c.instruction,job:{child_index:idx,...job},research:rr})}`;const o=await gm(prompt);const stance=["oppose","revise","withdraw","support","question"].includes(o?.stance)?o.stance:"question",message=String(o?.message||"").slice(0,1200)||"追加確認が必要です。",confidence=Number(o?.confidence||0);const out={child_index:idx,stance,message,confidence,provider:"google-gemini",needs_independent_recheck:false};outcomes.push(out);events.push({event_id:crypto.randomUUID(),job_id:`${p.parent}-${String(idx).padStart(2,"0")}`,role:"challenger",provider:"google-gemini",event_type:"challenge",summary:message,evidence:(o?.evidence??[]).slice(0,10).map((v:any)=>({kind:"challenge-reference",ref:String(v).slice(0,1500)})),severity:["oppose","question"].includes(stance)?"high":stance==="revise"?"medium":"info",state:"CHALLENGING",created_at:new Date().toISOString(),discussion:{command_id:c.id,child_index:idx,stage:"gemini-challenge",round,model:GEMINI,stance,confidence,questions:(o?.questions??[]).slice(0,5),checkpoint_resume:true},availability:{primary_provider:"google-gemini",status:"online",model:GEMINI}})}if(events.length)await add(raw,c.id,events);const needs=needsRevision({outcomes});await add(raw,c.id,[{event_id:crypto.randomUUID(),job_id:p.parent,role:"system",provider:"orchestrator",event_type:"status",summary:needs?"Gemini再検証で修正・確認論点を検出。完了済み工程には戻らず、この修正版を編集部内で再修正します。":"Gemini再検証を通過。完了済み工程には戻らず次工程へ進みます。",evidence:[],severity:needs?"medium":"info",state:needs?"CHALLENGING":"PLANNING",created_at:new Date().toISOString(),discussion:{command_id:c.id,stage:"challenge-complete",round,outcomes,needs_independent_recheck:false,article_build_allowed:true,checkpoint_resume:true},availability:{primary_provider:"google-gemini",status:"online",model:GEMINI}}]);return{needs_revision:needs,outcomes}}

async function revise(raw:string,c:any,p:any,r:any,ch:any,round:number){await patch(raw,c.id,"reviewing",null);const prompt=`denkicontrol.comのGPT編集長。Geminiの検証指摘を受け、既に完了した企画・Web調査はやり直さず、現在の企画だけを修正。公式調査で確認できない具体値・機種依存仕様は削除または一般論へ狭め、安全側に修正。案件数と順序を維持。\n指示:${c.instruction}\n現在の企画:${JSON.stringify(p.result.jobs)}\n既存調査:${JSON.stringify(r.results??[])}\nGemini指摘:${JSON.stringify(ch.outcomes??[])}`;const b=await oa({model:EDITOR,store:false,reasoning:{effort:"low"},input:prompt,text:{format:{type:"json_schema",name:"checkpoint_revised_plan",strict:true,schema:{type:"object",additionalProperties:false,required:["summary","jobs"],properties:{summary:{type:"string"},jobs:{type:"array",items:{type:"object",additionalProperties:false,required:["title","goal","content_type","priority","needs_research","research_brief"],properties:{title:{type:"string"},goal:{type:"string"},content_type:{type:"string",enum:["new_article","article_update","site_improvement","research","other"]},priority:{type:"string",enum:["high","medium","low"]},needs_research:{type:"boolean"},research_brief:{type:"string"}}}}}}}}});const x=JSON.parse(textOf(b));if(!Array.isArray(x.jobs)||x.jobs.length!==p.result.jobs.length)throw new Error("revision job count mismatch");const now=new Date().toISOString();await add(raw,c.id,[{event_id:crypto.randomUUID(),job_id:p.parent,role:"editor",provider:"openai-editor",event_type:"revision",summary:`Gemini指摘を編集部内で自動修正しました（${round}/${MAX}）。${String(x.summary||"").slice(0,1200)}`,evidence:[],severity:"info",state:"REVIEWING",created_at:now,discussion:{command_id:c.id,stage:"editor-auto-revision",round,model:EDITOR,checkpoint_resume:true},availability:{primary_provider:"openai-editor",status:"online",model:EDITOR}},...x.jobs.map((j:any,i:number)=>({event_id:crypto.randomUUID(),job_id:`${p.parent}-${String(i+1).padStart(2,"0")}`,role:"editor",provider:"openai-editor",event_type:"revision",summary:`${j.title}\n${j.goal}`.slice(0,2000),evidence:[],severity:"info",state:"REVIEWING",created_at:now,discussion:{command_id:c.id,child_index:i+1,stage:"editor-auto-revision",round,model:EDITOR,checkpoint_resume:true},availability:{primary_provider:"openai-editor",status:"online",model:EDITOR}}))]);return{...p,result:{...p.result,summary:x.summary,jobs:x.jobs}}}

async function autonomousLimit(raw:string,c:any,p:any,round:number){await patch(raw,c.id,"building",null);await add(raw,c.id,[{event_id:crypto.randomUUID(),job_id:p.parent,role:"reviewer",provider:"orchestrator",event_type:"status",summary:`自動修正を${round}回行っても独立検証の論点が残っています。途中で管理者確認へ止めず、安全側の一般化と警告を保持したまま制作・最終Preview監査へ進みます。`,evidence:[],severity:"high",state:"BUILDING",created_at:new Date().toISOString(),discussion:{command_id:c.id,stage:"revision-limit-degraded-continue",rounds:round,article_build_allowed:true,autonomous_degraded:true,human_gate_policy:"final-preview-only",checkpoint_resume:true},availability:{primary_provider:"orchestrator",status:"online"}}])}

Deno.serve(async req=>{if(req.method==="OPTIONS")return new Response(null,{status:204,headers:H});if(req.method!=="POST")return J({error:"method not allowed"},405);const raw=req.headers.get("authorization")??"";if(!raw.toLowerCase().startsWith("bearer "))return J({error:"authentication required"},401);let input:any={};try{input=await req.json()}catch{return J({error:"invalid json"},400)}const id=String(input.command_id??"");if(!/^[0-9a-f-]{36}$/i.test(id))return J({error:"valid command_id required"},400);let snap:any,c:any;try{snap=await rpc(raw,"ai_editorial_resume_snapshot",{p_command_id:id});c=snap.command;if(!snap.available||!Array.isArray(snap.jobs)||!snap.jobs.length){const rr=await fetch(`${U}/functions/v1/ai-editorial-process-command`,{method:"POST",headers:{Authorization:raw,apikey:K,"Content-Type":"application/json"},body:JSON.stringify({command_id:id,resume:true})});const tx=await rr.text();return new Response(tx,{status:rr.status,headers:H})}let p=plannedFrom(snap),r=researchFrom(snap),round=Math.max(0,Number(snap.revision_round||0)),latestStage=String(snap?.latest?.stage||"");let resumeLabel=latestStage==="editor-auto-revision"?`GPT修正${round}/${MAX}の次のGemini再検証`:latestStage==="challenge-complete"?"Gemini指摘後の修正工程":latestStage.includes("research")?"Web調査後のGemini検証":"保存済みチェックポイントの次工程";await add(raw,id,[{event_id:crypto.randomUUID(),job_id:p.parent,role:"system",provider:"orchestrator",event_type:"status",summary:`完了済みの企画・Web調査は再実行せず、${resumeLabel}から再開します。`,evidence:[],severity:"info",state:"PLANNING",created_at:new Date().toISOString(),discussion:{command_id:id,stage:"checkpoint-resume",resume_from:latestStage,revision_round:round,retry_policy:"same-queue"},availability:{primary_provider:"orchestrator",status:"online"}}]);r=await fillMissingResearch(raw,c,p,r);let ch:any;if(latestStage==="challenge-complete"&&needsRevision(snap.challenge_complete)){if(round>=MAX){await autonomousLimit(raw,c,p,round);return J({ok:true,status:"building",reason:"revision-limit-degraded-continue"})}round++;p=await revise(raw,c,p,r,{outcomes:snap.challenge_complete.outcomes??[]},round);ch=await challenge(raw,c,p,r,round)}else{ch=await challenge(raw,c,p,r,round)}while(ch.needs_revision&&round<MAX){round++;p=await revise(raw,c,p,r,ch,round);ch=await challenge(raw,c,p,r,round)}if(ch.needs_revision){await autonomousLimit(raw,c,p,round);return J({ok:true,status:"building",reason:"revision-limit-degraded-continue"})}if(Number(snap.routine_day)===1){return J({ok:true,command_id:id,status:"completed",resume_from:latestStage,revision_rounds:round,next:"weekly-plan-saved"})}await patch(raw,id,"building",null);await add(raw,id,[{event_id:crypto.randomUUID(),job_id:p.parent,role:"reviewer",provider:"orchestrator-reviewer",event_type:"review",summary:"Gemini再検証を通過。完了済み工程は再実行せず、制作・Preview工程へ進みます。",evidence:[],severity:"info",state:"BUILDING",created_at:new Date().toISOString(),discussion:{command_id:id,stage:"prebuild-review-pass",revision_rounds:round,checkpoint_resume:true},availability:{primary_provider:"orchestrator-reviewer",status:"online"}}]);return J({ok:true,command_id:id,status:"building",resume_from:latestStage,revision_rounds:round})}catch(e){const m=e instanceof Error?e.message:String(e);try{if(c?.id)await patch(raw,c.id,"failed",m)}catch{}return J({ok:false,error:m},500)}});